       }

       .hero {
         padding: 2rem;
         border: 1px solid rgba(218, 210, 197, 0.85);
         border-radius: 32px;
         background: var(--surface);
         backdrop-filter: blur(14px);
         box-shadow: var(--shadow);
       }

       .eyebrow {
         margin: 0 0 0.75rem;
         color: var(--accent-strong);
         font-size: 0.92rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 3.5rem);
         line-height: 1.05;
       }

       .lede {
         max-width: 65ch;
         margin: 1rem 0 0;
         color: var(--muted);
         font-size: 1.05rem;
       }

       .faq {
         display: grid;
         gap: 1rem;
         margin-top: 1.5rem;
       }

       .example {
         border: 1px solid var(--border);
         border-radius: var(--radius);
         background: rgba(255, 255, 255, 0.78);
         box-shadow: 0 10px 28px rgba(57, 45, 27, 0.08);
         overflow: clip;
       }

       .example h2 {
         margin: 0;
       }

       .faq-trigger {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         width: 100%;
         padding: 1.25rem 1.35rem;
         border: 0;
         background: transparent;
         color: inherit;
         font: inherit;
         text-align: left;
         cursor: pointer;
       }

       .faq-trigger::after {
         content: "+";
         flex: 0 0 auto;
         display: grid;
         place-items: center;
         width: 2rem;
         height: 2rem;
         border-radius: 999px;
         background: #f6e5d3;
         color: var(--accent-strong);
         font-size: 1.25rem;
         font-weight: 700;
         transition: transform 0.2s ease, background 0.2s ease;
       }

       .faq-trigger[aria-expanded="true"]::after {
         content: "−";
         background: #f3caa3;
       }

       .faq-trigger:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: -3px;
       }

       .details {
         padding: 0 1.35rem 1.25rem;
         color: var(--muted);
       }

       .details p {
         margin: 0;
       }

       .details p + p {
         margin-top: 0.85rem;
       }

       .details ul {
         margin: 0.85rem 0 0;
         padding-left: 1.25rem;
       }

       .details li + li {
         margin-top: 0.4rem;
       }

       .details strong {
         color: var(--text);
       }

       .supporting-note {
         margin-top: 1rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       @media (max-width: 640px) {
         main {
           padding-inline: 0.85rem;
           padding-top: 4.25rem;
         }

         .hero {
           padding: 1.35rem;
           border-radius: 24px;
         }

         .faq-trigger {
           padding: 1.05rem 1.1rem;
         }

         .details {
           padding-inline: 1.1rem;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         html {
           scroll-behavior: auto;
         }

         *,
         *::before,
         *::after {
           transition-duration: 0.01ms !important;
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
         }
       }

       @media (forced-colors: active) {
         :root {
           --surface: Canvas;
           --surface-strong: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: CanvasText;
           --accent: Highlight;
           --accent-strong: HighlightText;
           --shadow: none;
         }

         .hero,
         .example {
           forced-color-adjust: auto;
         }

         .skip-link,
         .faq-trigger::after,
         .faq-trigger:focus-visible {
           forced-color-adjust: none;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main" tabindex="-1">
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Cat care guide</p>
         <h1 id="page-title">Frequently asked questions about cats</h1>
         <p class="lede">
           Quick answers to common cat questions, from behavior and grooming to
           healthy routines and a few everyday myths.
         </p>
')

