const { chromium } = require('playwright');
const axe = require('axe-core');
const fs = require('fs');
const path = require('path');

(async () => {
  const file = 'file://' + path.resolve('index.html');
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto(file);
  await page.addScriptTag({ content: axe.source });

  const initial = await page.evaluate(() => Array.from(document.querySelectorAll('.details')).every((el) => el.hidden));
  if (!initial) throw new Error('FAQ panels are not collapsed by default');

  await page.click('#faq-1-trigger');
  const opened = await page.$eval('#faq-1', (el) => !el.hidden);
  if (!opened) throw new Error('FAQ panel did not open');

  const results = await page.evaluate(async () => await window.axe.run());
  const violations = results.violations.filter((v) => !v.tags.includes('best-practice'));
  if (violations.length) {
    console.log(JSON.stringify(violations.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })), null, 2));
    process.exit(1);
  }

  await browser.close();
  console.log('ok');
})();
